insert into promos (id, creator_profile_id, slug, lang, title, description, i18n, status, cta_kind, cta_url, cta_safety_status, has_perk, rights_confirmed_at, submitted_at, approved_at, live_at) select '6731222e-5585-57ce-b02e-064bc8ebe857', id, 'nicheable-simple-pages', 'en', 'Simple pages. Your plans. One place.', 'Undated planners you can print or use on an E-Ink tablet, plus a rental tax tracker with income and costs on one page.', '{"title":{"en":"Simple pages. Your plans. One place.","es":"Páginas simples. Tus planes. Un solo lugar.","tr":"Sade sayfalar. Senin planların. Tek yerde."},"desc":{"en":"Undated planners you can print or use on an E-Ink tablet, plus a rental tax tracker with income and costs on one page.","es":"Planificadores sin fecha para imprimir o usar en una tableta E-Ink, y un control de impuestos de alquiler con ingresos y gastos en una sola página.","tr":"Yazdırabileceğin ya da E-Ink tablette kullanabileceğin tarihsiz planlayıcılar ve gelir giderini tek sayfada tutan kiralama vergi takibi."}}', 'live', 'shop', 'https://nicheable.etsy.com', 'safe', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now') from profiles where handle = 'nicheable' on conflict do nothing;
insert into promo_videos (id, promo_id, label, mp4_url, webm_url, poster_url, duration_ms, width, height) select '3e603154-1aa4-5daf-a3e1-98411ffc1f34', id, 'A', 'https://promovote.com/media/nicheable-simple-pages.mp4', 'https://promovote.com/media/nicheable-simple-pages.webm', 'https://promovote.com/media/nicheable-simple-pages-poster.jpg', 22000, 720, 1280 from promos where id = '6731222e-5585-57ce-b02e-064bc8ebe857' on conflict do nothing;
insert into hashtags (tag, use_count) values ('planner', 1), ('productivity', 1), ('digitalplanner', 1) on conflict (tag) do update set use_count = use_count + 1;
insert into promo_hashtags (promo_id, tag, position) select id, t.tag, t.pos from promos, (select 'planner' as tag, 0 as pos union all select 'productivity' as tag, 1 as pos union all select 'digitalplanner' as tag, 2 as pos) t where promos.id = '6731222e-5585-57ce-b02e-064bc8ebe857' on conflict do nothing;
